output_text:
[
  {
    "id": "no_hand_carrying",
    "text": "Items should not be carried by hand; shoppers must avoid states in which their hands are full.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "hand_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "take_entry_cart",
    "text": "At the start of the trip, the shopper is obliged to take the cart stationed at the entrance.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "entry_cart_pickup": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "entry_cart_pickup"
    }
  },
  {
    "id": "cart_required_for_shelf_pickup",
    "text": "A shopper may pick up shelf items only while possessing a cart, so item collection must be cart-loading rather than hand-carrying.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cart_item_pickup": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        },
        "noncart_item_pickup": {
          "pre": {
            "and": [
              "without_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "noncart_item_pickup"
    }
  },
  {
    "id": "park_cart_at_service_counter",
    "text": "When a shopper brings a cart to the service counter, they are obliged to park or present the cart there.",
    "abstraction": {
      "state_properties": {
        "service_counter": "at(0,1)"
      },
      "events": {
        "arrive_service_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "service_counter",
              "hasCart"
            ]
          }
        },
        "park_cart_at_service": {
          "pre": {
            "and": [
              "service_counter",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "service_counter",
              "cartAt(0,1)"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arrive_service_with_cart",
      "discharge": "park_cart_at_service"
    }
  },
  {
    "id": "reclaim_service_cart",
    "text": "After parking the cart at the service counter, the shopper is obliged to reclaim it before leaving the store.",
    "abstraction": {
      "state_properties": {
        "service_counter": "at(0,1)",
        "cart_parked_at_service": "cartAt(0,1)"
      },
      "events": {
        "park_cart_at_service": {
          "pre": {
            "and": [
              "service_counter",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_service"
        },
        "pickup_service_cart": {
          "pre": {
            "and": [
              "service_counter",
              "cart_parked_at_service",
              "PICKUP_CART"
            ]
          },
          "post": {
            "and": [
              "service_counter",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart_at_service",
      "discharge": "pickup_service_cart"
    }
  },
  {
    "id": "depart_east_after_service_pickup",
    "text": "Once the shopper has reclaimed the cart at the service counter, they are obliged to depart that counter to the east.",
    "abstraction": {
      "state_properties": {
        "service_counter": "at(0,1)"
      },
      "events": {
        "pickup_service_cart": {
          "pre": {
            "and": [
              "service_counter",
              "cartAt(0,1)",
              "PICKUP_CART"
            ]
          },
          "post": {
            "and": [
              "service_counter",
              "hasCart"
            ]
          }
        },
        "east_departure_from_service": {
          "pre": {
            "and": [
              "service_counter",
              "hasCart",
              "E"
            ]
          },
          "post": {
            "and": [
              "at(1,1)",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_service_cart",
      "discharge": "east_departure_from_service"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "The shopper is forbidden to exit the supermarket without possessing the cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "exit_without_cart": {
          "pre": {
            "and": [
              "EXIT",
              "without_cart"
            ]
          },
          "post": null
        },
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "hasCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_without_cart"
    }
  },
  {
    "id": "cart_restricted_upper_aisles",
    "text": "Carts are prohibited in the upper restricted aisles and may not be pushed south from the narrow cell at (8,3).",
    "abstraction": {
      "state_properties": {
        "top_row": {
          "or": [
            "at(0,0)",
            "at(1,0)",
            "at(2,0)",
            "at(3,0)",
            "at(4,0)",
            "at(5,0)",
            "at(6,0)",
            "at(7,0)",
            "at(8,0)",
            "at(9,0)"
          ]
        },
        "upper_right_aisle": {
          "or": [
            "at(2,1)",
            "at(3,1)",
            "at(4,1)",
            "at(5,1)",
            "at(6,1)",
            "at(7,1)",
            "at(8,1)",
            "at(9,1)"
          ]
        },
        "cart_in_upper_restricted_area": {
          "and": [
            "hasCart",
            {
              "or": [
                "top_row",
                "upper_right_aisle"
              ]
            }
          ]
        }
      },
      "events": {
        "push_cart_south_from_8_3": {
          "pre": {
            "and": [
              "at(8,3)",
              "hasCart",
              "S"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_in_upper_restricted_area",
          "push_cart_south_from_8_3"
        ]
      }
    }
  }
]
